    "dockerfile": "FROM mshkn-base\nRUN mkdir -p /verb && printf '%s\\n' '#!/usr/bin/perl' 'use strict; use warnings; use Socket;' 'my $url=shift // die \"missing URL\\n\"; $url =~ m{^(https?)://([^/]+)(/.*)?$}i or die \"HTTP/HTTPS URL required\\n\";' 'my ($scheme,$authority)=(lc($1),$2); $authority !~ /\\@/ or die \"credentials not allowed\\n\";' 'my ($host,$port); if ($authority =~ /^([A-Za-z0-9.-]+)(?::([0-9]+))?$/) { ($host,$port)=($1,$2) } else { die \"invalid hostname\\n\" }' '$port ||= $scheme eq \"https\" ? 443 : 80; ($port==80 || $port==443) or die \"only ports 80/443 allowed\\n\";' 'my $packed=gethostbyname($host) or die \"DNS failed\\n\"; my $ip=inet_ntoa($packed); my @o=split /\\./,$ip;' 'my $bad=($o[0]==0||$o[0]==10||$o[0]==127||$o[0]>=224||($o[0]==100&&$o[1]>=64&&$o[1]<=127)||($o[0]==169&&$o[1]==254)||($o[0]==172&&$o[1]>=16&&$o[1]<=31)||($o[0]==192&&$o[1]==168)||($o[0]==198&&($o[1]==18||$o[1]==19))||($o[0]==192&&$o[1]==0&&($o[2]==0||$o[2]==2))||($o[0]==198&&$o[1]==51&&$o[2]==100)||($o[0]==203&&$o[1]==0&&$o[2]==113)); die \"destination not public IPv4\\n\" if $bad;' 'my $tmp=\"/tmp/page.$$\"; my $meta=\"/tmp/meta.$$\"; my @cmd=(\"curl\",\"--silent\",\"--show-error\",\"--fail\",\"--proto\",\"=http,https\",\"--max-time\",\"15\",\"--connect-timeout\",\"7\",\"--max-filesize\",\"1048576\",\"--max-redirs\",\"0\",\"--noproxy\",\"*\",\"--resolve\",\"$host:$port:$ip\",\"--output\",$tmp,\"--write-out\",\"%{url_effective}\\\\n%{content_type}\\\\n%{size_download}\",\"--user-agent\",\"read_page/1.0\",$url);' 'open my $old,\">&\",\\*STDOUT or die; open my $mh,\">\",$meta or die; open STDOUT,\">&\",$mh or die; system @cmd; my $rc=$?; open STDOUT,\">&\",$old or die; close $mh; close $old; if ($rc != 0) { unlink $tmp,$meta; die \"fetch failed; redirects not followed\\n\" }' 'open $mh,\"<\",$meta or die; my @m=<$mh>; close $mh; chomp @m; my ($final,$ct,$size)=@m; open my $fh,\"<:raw\",$tmp or die; local $/; my $body=<$fh>; close $fh; unlink $tmp,$meta; length($body)<=104